import axios from 'axios';

// Dynamically choose API base URL depending on environment
let baseURL;

if (process.env.REACT_APP_API_URL) {
  // Use .env value if available (e.g. in production)
  baseURL = process.env.REACT_APP_API_URL;
} else if (
  window.location.hostname === 'localhost' ||
  window.location.hostname === '127.0.0.1'
) {
  // Running locally (React dev server)
  baseURL = 'http://127.0.0.1:5001/api';
} else {
  // Production (served via Nginx on same origin)
  baseURL = '/api';
}

// Create axios instance
const instance = axios.create({
  baseURL,
  // Uncomment if your backend sets auth cookies:
  // withCredentials: true,
});

export default instance;
